    fetchChips()
      .then((d) => {
        setChips(d.chips);
        if (d.chips.length) setChip(d.chips[0]);
      })
      .catch(() => {});
  }, []);

  const branch = events.length ? events[events.length - 1].branch : null;

  async function handleLaunch() {
    setLaunching(true);
    setLaunchError(null);
    try {
      await startRun({ chip, attempts, parallel: parallel && attempts > 1 });
