import { chromium } from "playwright";

const errors = [];
const browser = await chromium.launch();
const page = await browser.newPage();
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await page.waitForSelector("text=CHIP RECREATION");

// should have leftover events from the earlier real run still in history
await page.waitForSelector(".agent-status-row", { timeout: 10000 });
const before = await page.$$eval(".agent-status-row", (els) => els.length);
console.log("agent status rows BEFORE reset:", before);

await page.screenshot({ path: "scratch_reset_before.png", fullPage: true });

await page.click("button:has-text('Reset')");
await page.waitForTimeout(800);

const after = await page.$$eval(".agent-status-row", (els) => els.length);
console.log("agent status rows AFTER reset:", after);
const emptyMsg = await page.$eval(".agent-status-empty", (el) => el.textContent).catch(() => null);
console.log("empty-state message:", emptyMsg);

await page.screenshot({ path: "scratch_reset_after.png", fullPage: true });

console.log("console errors:", JSON.stringify(errors));
await browser.close();

