import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage();

let dialogMessage = null;
page.on("dialog", async (dialog) => {
  dialogMessage = dialog.message();
  await dialog.accept(); // simulate clicking OK
});

await page.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await page.waitForSelector("text=CHIP RECREATION");

await page.click("button:has-text('Kill All Orchestrators')");
await page.waitForTimeout(1500);

console.log("dialog shown:", dialogMessage);
const resultText = await page.$eval(".app-kill-result", (el) => el.textContent).catch(() => null);
console.log("UI result text:", resultText);

await page.screenshot({ path: "scratch_killall.png", fullPage: true });
await browser.close();

